      "path": "src/index.ts",
      "content": "// dsh-heartbeat plugin entry.\n//\n// Contract (verified against DSH 0.1.1-rc.2 + dsh-vision-router as the\n// third-party reference): the package main exports a cordis plugin -\n// { name, inject, Config, apply(ctx, config) }. The bundle-level\n// cordis.patch.yml (dsh.bundle.patch) mounts it via\n//   - insert: - id: heartbeat, name: dsh-heartbeat\n// and the loader resolves `name` to this package's main export.\n\nimport z from '@deepseek-ai/schemastery';\nimport { initWorkspace } from './core/paths.js';\nimport { createPathGuard } from './core/path-guard.js';\nimport { appendAuditLine } from './core/audit-log.js';\nimport { loadPolicy, updateUserPolicy } from './config/load.js';\nimport { loadUiConfig, saveUiConfig, type UiConfig } from './config/ui-config.js';\nimport { resolveQuietHours } from './config/quiet-hours.js';\nimport { deepMerge } from './config/schema.js';\nimport { setRuntime, getRuntime } from './core/runtime.js';\nimport { startOrchestrator, applyHeartbeatInterval, type OrchestratorDeps } from './core/orchestrator.js';\nimport { installHeartbeatRpc } from './rpc.js';\nimport { registerTimeInjection } from './statusbar/time-inject.js';\nimport { registerStatusbarSection, noteTrack, pinTrack } from './statusbar/track.js';\nimport { StatusReader } from './statusbar/store.js';\nimport { renderStatusText } from './statusbar/track.js';\nimport { installBundledPreset, userPresetRoot, describeInstall } from './core/preset-install.js';\nimport { registerHeartbeatPreset } from './core/preset-definition.js';\nimport { buildLedgerTool } from './ledger/tool.js';\nimport { buildSeedReportTool, reportFilePath } from './seeds/report.js';\nimport { ledgerFilePath } from './ledger/ledger.js';\nimport { buildNotepadTool } from './notepad/tool.js';\nimport { notepadFilePath } from './notepad/store.js';\nimport { buildExcerptTool } from './excerpt/tool.js';\nimport { excerptFilePath } from './excerpt/excerpt.js';\nimport { startBilibiliSource } from './sources/bilibili.js';\n\nexport const name = 'heartbeat';\n\n/**\n * Host services required by the orchestrator (verified present in\n * DSH 0.1.1-rc.2 via hb-probe: agents service + agent/created + followup).\n *\n * `settings` is deliberately NOT declared here (v2.1.0, from issue #6's follow-up):\n * a module-level `inject` entry is a HARD dependency — cordis keeps the plugin\n * at `pending (waiting for service: settings)` for as long as the host does not\n * provide it, and on DSH desktop 0.2.1-rc.3 that pending plugin was enough to\n * take the shell down (\"Web RPC failed\" in openInitialWindow, then a crash dialog\n * whose three buttons did nothing). The settings form is a convenience, not a\n * prerequisite: rhythm values come from data/settings/ui.json plus the apply-time\n * `config` either way. It is attached lazily through `ctx.inject(['settings'], …)`\n * below, so the heartbeat starts on `agents` alone and picks the form up whenever\n * the service appears.\n */\nexport const inject = ['agents'];\n\nexport const Config = z.object({\n  /** Override the runtime data dir (workspace guard boundary). Empty = default (<packageRoot>/data). */\n  dataDir: z.string().default(''),\n  /** UI-editable: heartbeat interval in minutes. 0 = use policy file / factory. */\n  intervalMin: z.number().default(0),\n  /** UI-editable: daily expression cap. 0 = use policy file / factory. */\n  maxDailySend: z.number().default(0),\n  /**\n   * Agent preset the heartbeat agent joins (`<dshHome>/.agent-presets/<id>/`).\n   * Without a preset the agent is a BARE agent: tools/prompt sections resolve\n   * against the empty global layer, so it cannot even see `web_search`.\n   */\n  agentPreset: z.string().default('heartbeat'),\n  /**\n   * Install the bundled preset (see `agentPreset`) into the roster's user root\n   * on first run, so setup needs no manual file copy. An existing preset is\n   * never overwritten; set false to manage the preset entirely by hand.\n   */\n  installPreset: z.boolean().default(true),\n  /** Self-built time injection interval (D20, §17.6). 0 disables injection.\n   *  Left OPTIONAL on purpose (2026-10-17): a schema default here is\n   *  indistinguishable from an explicit choice, and `applySettingsOverrides`\n   *  applies this value over ui.json — so a default would silently undo the\n   *  card on every reload. Unset falls back at the refs below. */\n  timeInjectMin: z.number(),\n  /** IANA timezone for the injected clock; empty = process zone. */\n  timeZone: z.string().default(''),\n  /** Statusbar master switch (D19). Off = no section/pre-step status; time injection unaffected. */\n  statusbar: z.boolean(),\n  /** v1.6.3 闲着模式：素材池为空时用画像话题兜底主动搭话（默认关）。 */\n  idleMode: z.boolean(),\n  /** v1.7.0 节省 token 模式：用户离开（闲置 ≥30 分钟）或锁屏时整跳暂停（默认关）。 */\n  tokenSaver: z.boolean(),\n  /** v1.8.0 账本工具：向所有日常会话 agent 注册共享账本工具（默认开）。 */\n  ledgerTool: z.boolean().default(true),\n  /** v1.9.0 素材报账工具：投递后由陪伴 agent 主动报账（默认开）。 */\n  seedReportTool: z.boolean().default(true),\n  /** v2.0.0 心事匣工具：留给下一跳的一句便签（默认开）。 */\n  notepadTool: z.boolean().default(true),\n  /** v2.0.0 摘抄本工具：留句子和小事的地方（默认开）。 */\n  excerptTool: z.boolean().default(true),\n  /** v1.8.0 引擎室追加工具：逗号分隔的全局工具名，存在才加入白名单（bili 压缩工具自动探测，无需手填）。 */\n  extraTools: z.string().default(''),\n  /**\n   * 视觉识别引擎（v2.2.1-native.1）：`auto` / `native` / `modlens`。\n   * 留空 = 跟随 `data/settings/vision.json` 的 engine，再回落到内置默认 auto。\n   * 这里给一个正式设置项，是为了让\"默认走哪条路\"可以不改代码就调——\n   * 例如想保守地维持 v2.2.1 行为（只用 ModLens）就填 `modlens`。\n   */\n  visionEngine: z.string().default(''),\n});\n\nexport interface HeartbeatConfig {\n  dataDir?: string | null;\n  intervalMin?: number;\n  maxDailySend?: number;\n  agentPreset?: string;\n  installPreset?: boolean;\n  timeInjectMin?: number;\n  timeZone?: string;\n  statusbar?: boolean;\n  idleMode?: boolean;\n  tokenSaver?: boolean;\n  ledgerTool?: boolean;\n  seedReportTool?: boolean;\n  notepadTool?: boolean;\n  excerptTool?: boolean;\n  extraTools?: string;\n  /** v2.2.1-native.1: vision engine ('' = vision.json → built-in auto). */\n  visionEngine?: string;\n}\n\nexport function apply(ctx: OrchestratorDeps['ctx'] & {\n  get(name: string): unknown;\n  /** Cordis lazy service declaration: callback runs once the named services mount. */\n  inject(services: string[], callback: (scoped: unknown) => void): void;\n  /** Cordis event subscription (pre-step waterfall etc.); returns a disposer. */\n  on(event: string, listener: (payload: never, next: () => Promise<unknown>) => Promise<unknown>, opts?: { prepend?: boolean }): unknown;\n}, config: HeartbeatConfig = {}): void {\n  const paths = initWorkspace(config.dataDir ? { dataDir: config.dataDir } : {});\n  const guard = createPathGuard(paths.dataDir);\n  let policy = loadPolicy(guard, paths.configDir, paths.settingsDir);\n\n  // Card-edited rhythm values (v1.7.0, data/settings/ui.json): the settings\n  // card writes these over RPC. Precedence: policy layers < ui.json < the\n  // composition-entry config below.\n  const ui = loadUiConfig(guard, paths.settingsDir);\n  if (ui.intervalMin && ui.intervalMin >= 1) {\n    policy = { ...policy, heartbeat: { ...policy.heartbeat, intervalMin: ui.intervalMin } };\n  }\n  if (ui.maxDailySend && ui.maxDailySend >= 1) {\n    policy = { ...policy, gate: { ...policy.gate, maxDailySend: ui.maxDailySend } };\n  }\n\n  // Composition-entry overrides (the patch row's config block).\n  if (config.intervalMin && config.intervalMin >= 1) {\n    policy = { ...policy, heartbeat: { ...policy.heartbeat, intervalMin: config.intervalMin } };\n  }\n  if (config.maxDailySend && config.maxDailySend >= 1) {\n    policy = { ...policy, gate: { ...policy.gate, maxDailySend: config.maxDailySend } };\n  }\n\n  const deps: OrchestratorDeps = {\n    ctx, paths, guard, policy,\n    agentPreset: config.agentPreset || 'heartbeat',\n    extraTools: (config.extraTools ?? '').split(',').map((s) => s.trim()).filter(Boolean),\n    presetRegistration: () => presetRegistration ?? Promise.resolve(),\n  };\n  setRuntime({\n    paths,\n    guard,\n    policy,\n    flags: {\n      statusbarEnabled: () => statusbarEnabledRef,\n      timeInjectMin: () => timeInjectMinRef,\n      idleMode: () => idleModeRef,\n      tokenSaver: () => tokenSaverRef,\n      // v2.2.1-native.1: card / composition engine choice ('' = vision.json).\n      // Lazy on purpose: the refs below are declared after this call.\n      visionEngine: () => effectiveVisionEngine(),\n    },\n  });\n\n  // Runtime preset registration (issue #2). The `agentPresets` inject below\n  // assigns it; the acquire path awaits it before mounting the preset.\n  let presetRegistration: Promise<void> | undefined;\n  /** HB-17: registry undo hook + whether dispose already ran (a reload must\n   *  not leave the preset behind, and an in-flight registration must still be\n   *  undone if dispose wins the race). */\n  let presetDisposer: (() => Promise<void>) | undefined;\n  let presetDisposed = false;\n\n  // ── Preset: runtime registration + filesystem install (C13 / issue #2) ───\n  // The preset is what lets the heartbeat agent see `web_search` at all, so\n  // the plugin owns it in both senses:\n  //\n  //  1. RUNTIME REGISTRATION (0.1.7+). The registry takes a definition\n  //     straight from the declaring plugin (`AgentPresetRegistry.register`),\n  //     so nothing in the composition has to name\n  //     `@deepseek-ai/dsh-agent-preset`. That matters: a profile cannot always\n  //     resolve it, and its peer closure contains Cordis's own loader — a\n  //     profile that ships those by hand double-instances the machinery, and\n  //     then every session refuses to resume (\"prompt section\n  //     deployment:persona-prefix is already registered\"), while one that\n  //     cannot resolve the package fails the WHOLE plugin tree at load\n  //     (reported 2026-10-10, both with reproductions). A host whose registry\n  //     has no `register` degrades to an audit line, never a throw.\n  //  2. FILESYSTEM INSTALL, kept for hosts that still scan the roster's user\n  //     root (`agentPresets.roots`, trust === \"user\"): first run writes the\n  //     bundled template under the roster's OWN root instead of a guessed\n  //     `~/.dsh`, so `$DSH_HOME`/a configured home are honoured; an existing\n  //     preset is never overwritten.\n  //\n  // `installPreset: false` means \"the operator manages the preset by hand\", so\n  // it switches BOTH off. Audit lines: `preset_register`, `preset_install`.\n  ctx.inject(['agentPresets'], (presetCtx: unknown) => {\n    const service = (presetCtx as {\n      agentPresets?: { roots?: Array<{ path?: string; trust?: string }> };\n    }).agentPresets;\n    const presetId = config.agentPreset || 'heartbeat';\n    const installEnabled = config.installPreset !== false;\n    const audit = (entry: Record<string, unknown>): void => {\n      try {\n        appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), entry);\n      } catch (e) {\n        ctx.logger.warn('heartbeat: preset audit failed (%s)', String(e).slice(0, 120));\n      }\n    };\n\n    presetRegistration = registerHeartbeatPreset(service, presetId, installEnabled).then((result) => {\n      audit({ event: 'preset_register', ...result });\n      if (typeof result.disposer === 'function') {\n        if (presetDisposed) {\n          // dispose already ran while registration was in flight: undo now.\n          void Promise.resolve(result.disposer()).catch((e) => {\n            ctx.logger.warn('heartbeat: preset dispose failed (%s)', String(e).slice(0, 120));\n          });\n        } else {\n          presetDisposer = result.disposer;\n        }\n      }\n      if (result.action === 'error') {\n        ctx.logger.warn('heartbeat: preset register failed (%s) — the engine room runs without it', result.detail ?? '');\n      } else if (result.action === 'registered') {\n        ctx.logger.info('heartbeat: preset %s registered at runtime', result.id);\n      } else if (result.action === 'already-registered') {\n        // HB-31: the previous instance still owns the id (same definition).\n        ctx.logger.info('heartbeat: preset %s already registered — reusing it', result.id);\n      } else {\n        ctx.logger.info('heartbeat: preset registration skipped (%s)', result.action);\n      }\n    });\n\n    const root = userPresetRoot(service?.roots);\n    const result = installBundledPreset({\n      moduleUrl: import.meta.url,\n      id: presetId,\n      ...(root === undefined ? { rosterKnown: service !== undefined } : { root }),\n      enabled: installEnabled,\n    });\n    audit({ event: 'preset_install', ...result });\n    const line = describeInstall(result);\n    if (result.action === 'error' || result.action === 'skipped-no-root') {\n      ctx.logger.warn('heartbeat: %s', line);\n    } else {\n      ctx.logger.info('heartbeat: %s', line);\n    }\n  });\n\n  // M6: settings section (namespace 'heartbeat') - the web card edits this\n  // namespace; resolved values apply live (interval reschedules the timer).\n  let sectionSource: (() => HeartbeatConfig) | null = null;\n  let timeInjectMinRef = ui.timeInjectMin ?? (config.timeInjectMin ?? 25);\n  // Factory default is OFF (v1.9.3); `=== true` so an UNSET config no longer\n  // reads as \"not false = on\" now that the schema leaves it optional.\n  let statusbarEnabledRef = ui.statusbar ?? (config.statusbar === true);\n  let idleModeRef = ui.idleMode ?? (config.idleMode === true);\n  let tokenSaverRef = ui.tokenSaver ?? (config.tokenSaver === true);\n  // v2.2.1-native.1: vision engine has TWO inputs and one effective value.\n  //   · the card's setting (ui.json) is what the user edits — the normal path;\n  //   · the composition/plugin config can pin it for a deployment, and wins\n  //     over the card exactly like the rhythm fields above do;\n  //   · '' follows data/settings/vision.json, then the built-in default (auto).\n  // Invalid values are neutralised in resolveVisionEnginePrecedence, so a typo\n  // can never crash a beat or override a deliberate vision.json.\n  let visionEngineConfigRef = config.visionEngine ?? '';\n  let visionEngineUiRef = ui.visionEngine ?? '';\n  const effectiveVisionEngine = (): string =>\n    visionEngineConfigRef.trim() || visionEngineUiRef.trim();\n\n  // H-48: ONE setter table for the live-settable fields. The settings section\n  // and the RPC uiSet path used to carry a copy each of the same six ifs, so a\n  // new field had to be added twice — and the two copies had already drifted\n  // (timeInjectMin's lower bound, tokenSaver's absence from the section path).\n  const applyLiveSettings = (v: {\n    intervalMin?: number;\n    maxDailySend?: number;\n    timeInjectMin?: number;\n    statusbar?: boolean;\n    idleMode?: boolean;\n    tokenSaver?: boolean;\n  }): void => {\n    if (v.intervalMin && v.intervalMin >= 1) applyHeartbeatInterval(deps, v.intervalMin);\n    if (v.maxDailySend && v.maxDailySend >= 1) getRuntime().policy.gate.maxDailySend = v.maxDailySend;\n    if (typeof v.timeInjectMin === 'number' && v.timeInjectMin >= 0) timeInjectMinRef = v.timeInjectMin;\n    if (typeof v.statusbar === 'boolean') statusbarEnabledRef = v.statusbar;\n    if (typeof v.idleMode === 'boolean') {\n      idleModeRef = v.idleMode;\n      getRuntime().policy.heartbeat.idleMode = v.idleMode;\n    }\n    if (typeof v.tokenSaver === 'boolean') tokenSaverRef = v.tokenSaver;\n  };\n\n  const applySettingsOverrides = (): void => {\n    try {\n      const v = sectionSource?.();\n      if (!v) return;\n      applyLiveSettings(v);\n      visionEngineConfigRef = typeof v.visionEngine === 'string' ? v.visionEngine : '';\n      ctx.logger.info('heartbeat: settings overrides live (interval %s, cap %s, timeInject %s)', v.intervalMin ?? '-', v.maxDailySend ?? '-', v.timeInjectMin ?? '-');\n    } catch (e) {\n      ctx.logger.warn('heartbeat: settings override failed (%s)', String(e).slice(0, 120));\n    }\n  };\n  // M6: settings form (namespace 'heartbeat'). Attached lazily through\n  // `ctx.inject` because the service is no longer in the module-level `inject`\n  // (see above): the callback runs once `settings` exists and its effects are\n  // disposed if the service ever goes away, while the heartbeat itself keeps\n  // running on `agents` alone.\n  //\n  // DSH 0.1.7 and later expose `SettingsForms`: plugin config forms render from\n  // the Config schema on the Plugins page, and an edit RELOADS this plugin (timers\n  // dispose via ctx.effect, so reloads are safe) — nothing to register here, the\n  // apply-time `config` is already the live source. The 0.1.5 `installSection`\n  // generation and the 0.1.1/0.1.2 free-function fallback are gone: they were\n  // reachable only on hosts the package no longer supports (README: DSH 0.2.1+),\n  // and they were the only reason `@deepseek-ai/dsh-settings` was a dependency.\n  ctx.inject(['settings'], (settingsCtx: unknown) => {\n    try {\n      const settingsService = (settingsCtx as { get(name: string): unknown }).get('settings') as\n        | { describe?(options?: unknown): unknown }\n        | undefined;\n      if (settingsService && typeof settingsService.describe === 'function') {\n        sectionSource = () => config;\n        applySettingsOverrides();\n        ctx.logger.info('heartbeat: config served by the profile settings form (edits reload the plugin)');\n        return;\n      }\n      ctx.logger.warn('heartbeat: settings service present but not a SettingsForms instance; policy file values only');\n    } catch (e) {\n      ctx.logger.warn('heartbeat: settings form unavailable (%s)', String(e).slice(0, 120));\n    }\n  });\n\n  appendAuditLine(\n    guard.assert(paths.logsDir + '/heartbeat.jsonl'),\n    { event: 'plugin_init', dataDir: paths.dataDir },\n  );\n\n  // issue #2: a package-local data dir is moved out of the package on first\n  // sight. The audit line is the only durable trace; a failed move keeps\n  // serving the legacy tree (and never deletes it).\n  if (paths.relocation) {\n    const auditFile = guard.assert(paths.logsDir + '/heartbeat.jsonl');\n    if (paths.relocation.action === 'relocated') {\n      appendAuditLine(auditFile, {\n        event: 'data_dir_relocated',\n        from: paths.relocation.srcDir,\n        to: paths.relocation.dstDir,\n        files: paths.relocation.files,\n        bytes: paths.relocation.bytes,\n        warnings: paths.relocation.warnings,\n        leftovers: paths.relocation.leftovers,\n      });\n      ctx.logger.info(\n        'heartbeat: data dir moved out of the package (%s files, %s bytes)',\n        paths.relocation.files,\n        paths.relocation.bytes,\n      );\n    } else if (paths.relocation.action === 'failed') {\n      appendAuditLine(auditFile, {\n        event: 'data_dir_relocate_failed',\n        stage: paths.relocation.stage,\n        problems: paths.relocation.problems,\n      });\n      ctx.logger.warn(\n        'heartbeat: data dir relocation failed (%s); continuing in the package dir',\n        paths.relocation.stage,\n      );\n    }\n  }\n\n  // ── M6 拓展：正式 RPC 通道（决策 1 = B 方案，探针已验证）──────────\n  // connection 晚挂载 → ctx.inject(['connection'], ...) 声明式等待；\n  // 端点分发见 src/rpc.ts（bindings/seeds/status/profile/ledger/config）。\n  // ui.get/uiSet：节律配置的活视图与\"落盘+即时生效\"（v1.7.0，data/settings/ui.json）。\n  // psyEnabled 例外：它是 policy 字段，写 data/settings/policy.json 用户层。\n  const uiGet = () => ({\n    intervalMin: getRuntime().policy.heartbeat.intervalMin,\n    maxDailySend: getRuntime().policy.gate.maxDailySend,\n    timeInjectMin: timeInjectMinRef,\n    statusbar: statusbarEnabledRef,\n    idleMode: idleModeRef,\n    tokenSaver: tokenSaverRef,\n    // card-stored choice ('' = follow vision.json); the effective engine also\n    // honours a composition-level config pin (see effectiveVisionEngine).\n    visionEngine: visionEngineUiRef,\n    psyEnabled: getRuntime().policy.profile.psyEnabled,\n    quietStart: getRuntime().policy.gate.quietHours.start,\n    quietEnd: getRuntime().policy.gate.quietHours.end,\n  });\n  const uiSet = (patch: UiConfig & { psyEnabled?: boolean; quietStart?: string; quietEnd?: string }): void => {\n    if (typeof patch.psyEnabled === 'boolean') {\n      updateUserPolicy(guard, paths.settingsDir, { profile: { psyEnabled: patch.psyEnabled } });\n      getRuntime().policy.profile.psyEnabled = patch.psyEnabled;\n    }\n    // 静默时段（v2.2）：policy 用户层字段，与 psyEnabled 同理不写 ui.json。\n    // runtime policy 是活引用（evaluateGate 每跳读它），改内存对象即下一跳生效。\n    if (patch.quietStart !== undefined || patch.quietEnd !== undefined) {\n      const next = resolveQuietHours(patch.quietStart, patch.quietEnd, getRuntime().policy.gate.quietHours);\n      if (!next) throw new Error('quiet hours must be HH:MM (00:00-23:59)');\n      updateUserPolicy(guard, paths.settingsDir, { gate: { quietHours: next } });\n      const q = getRuntime().policy.gate.quietHours;\n      q.start = next.start;\n      q.end = next.end;\n    }\n    const merged = saveUiConfig(guard, paths.settingsDir, patch);\n    visionEngineUiRef = merged.visionEngine ?? '';\n    applyLiveSettings(merged);\n  };\n  installHeartbeatRpc(ctx, { paths, guard, policy, ui: { get: uiGet, set: uiSet } });\n\n  // H-49: the ledger (v1.8.0) and seed_report (v1.9.0) registrations were two\n  // copies of one block — same audit closure, same try/catch, same degradation\n  // to an audit line on a host without a registerable ToolRuntime. One factory\n  // now covers both; the audit event names are unchanged.\n  const registerGlobalTool = (name: string, build: () => unknown): void => {\n    ctx.inject(['tools'], (scoped: unknown) => {\n      const audit = (entry: Record<string, unknown>): void => {\n        try {\n          appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), entry);\n        } catch { /* audit must never break startup */ }\n      };\n      try {\n        const tools = (scoped as { tools?: { register(definition: unknown): () => void } }).tools;\n        if (!tools || typeof tools.register !== 'function') throw new Error('ToolRuntime.register unavailable on this host');\n        tools.register(build());\n        audit({ event: `${name}_tool_registered` });\n      } catch (e) {\n        audit({ event: `${name}_tool_register_failed`, error: String(e).slice(0, 160) });\n      }\n    });\n  };\n\n  // ── Ledger as a model tool (v1.8.0) ─────────────────────────────────────\n  // Registers a shared `ledger` tool in the GLOBAL tool layer so every chat\n  // agent can record/complete todos without being commanded to. The engine\n  // room never sees it (its preset allow-list masks global tools). Definition\n  // is a plain object (no dsh-tools import); a host without a registerable\n  // ToolRuntime degrades to an audit line only.\n  if (config.ledgerTool !== false) {\n    registerGlobalTool('ledger', () => buildLedgerTool(guard, ledgerFilePath(paths.dataDir)));\n  }\n\n  // ── Seed report tool (v1.9.0): the persona files ONE report per delivery ─\n  // spoken / seed_ids / profile_ids / reason — the unified bookkeeping channel\n  // that replaced containment-match attribution. Same global-layer pattern as\n  // the ledger tool; the engine room never sees it.\n  if (config.seedReportTool !== false) {\n    registerGlobalTool('seed_report', () => buildSeedReportTool(guard, reportFilePath(paths.dataDir)));\n  }\n\n  // ── 心事匣 (v2.0.0): one note she leaves for the next beat ──────────────\n  // Same global-layer pattern, and the same reason as above: the engine room\n  // never sees this tool. It does not need to — the note reaches the next beat\n  // through the delivery package (material.ts notepadLines), which the engine\n  // room builds but never authors. Storage is encrypted (it is more private\n  // than the ledger), so the module goes through the vault, not plain text.\n  if (config.notepadTool !== false) {\n    registerGlobalTool('notepad', () => buildNotepadTool(guard, notepadFilePath(paths.dataDir)));\n  }\n\n  // ── 摘抄本 (v2.0.0): a line worth keeping, kept in plain text ───────────\n  // Same global-layer pattern. Unlike the notepad this one is plaintext on\n  // purpose: the settings card opens the file for the user, and a notebook\n  // nobody can read is not a notebook. The ledger is the other plaintext file.\n  if (config.excerptTool !== false) {\n    registerGlobalTool('excerpt', () => buildExcerptTool(guard, excerptFilePath(paths.dataDir)));\n  }\n\n  // §7 main loop: dedicated session/agent + timer (first beat after 15s).\n  startOrchestrator(deps);\n\n  // ── Bilibili watch-history source (v2.2, ledger #f575a6) ────────────────\n  // A passive 闲逛素材 feed on its OWN 2h timer — deliberately outside the\n  // beat phases (the orchestrator must not gain a network dependency): the\n  // source throttles itself from a persisted timestamp, fails silent (at most\n  // one debug line) and never touches the heartbeat main flow. The disposer\n  // clears the timer so a plugin reload cannot leak it.\n  ctx.effect(() => {\n    const audit = (entry: Record<string, unknown>): void => {\n      try {\n        appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), entry);\n      } catch { /* audit must never break the source */ }\n    };\n    const debug = (msg: string): void => {\n      try {\n        (ctx.logger as { debug?: (msg: string, ...a: unknown[]) => void }).debug?.('heartbeat: %s', msg);\n      } catch { /* debug sink is best-effort */ }\n    };\n    return startBilibiliSource({ guard, paths, policy: getRuntime().policy, audit, debug });\n  }, 'heartbeat: bilibili source');\n\n  // ── M7b: self-built time injection (D20, §17.6) ────────────────────────\n  // Gate: step===1 AND user-initiated AND ≥ timeInjectMin since the last\n  // injection for that session. Official dsh-time-context is disabled via the\n  // user patch (B9 superseded by D20 — single owner). The interval is\n  // live-settable: `timeInjectMinRef` is re-read on every gate check.\n  // ── M7c: statusbar two tracks (D19, §17.4–17.5) ─────────────────────────\n  // Track A (in-history models) rides a dynamic system-prompt section; Track B\n  // rides the same pre-step message as the time injection (§17.5 combined).\n  const statusReader = new StatusReader();\n  registerStatusbarSection(ctx, guard, paths, {\n    enabled: () => statusbarEnabledRef,\n    reader: statusReader,\n  });\n  ctx.effect(() => {\n    registerTimeInjection(ctx, guard, paths.dataDir, {\n      getTimeInjectMin: () => timeInjectMinRef,\n      timeZone: config.timeZone || undefined,\n      paths,\n      logger: ctx.logger,\n      onError: (e) => ctx.logger.warn('heartbeat: time injection skipped (%s)', String(e).slice(0, 120)),\n      pinTrack: (sessionId, session) => {\n        const track = pinTrack(sessionId, session);\n        noteTrack(paths.logsDir + '/heartbeat.jsonl', sessionId, track);\n        return track;\n      },\n      getStatusLine: (session, track) => {\n        if (!statusbarEnabledRef) {\n          noteTrack(paths.logsDir + '/heartbeat.jsonl', session.id, 'off');\n          return '';\n        }\n        return track === 'pre-step' ? renderStatusText(statusReader.read(guard, paths)) : '';\n      },\n    });\n    return undefined;\n  }, 'heartbeat: time injection');\n\n  // Host effect contract: fn runs immediately, returns the disposer.\n  ctx.effect(() => {\n    return () => {\n      presetDisposed = true;\n      const undoPreset = presetDisposer;\n      presetDisposer = undefined;\n      if (typeof undoPreset === 'function') {\n        void Promise.resolve(undoPreset()).catch((e) => {\n          ctx.logger.warn('heartbeat: preset dispose failed (%s)', String(e).slice(0, 120));\n        });\n      }\n      ctx.logger.info('heartbeat: disposed, timers cleaned up');\n    };\n  }, 'heartbeat: lifecycle');\n}\n\n// deepMerge is re-exported for the CLI status command layering.\nexport { deepMerge };\n"
    },
    {
      "path": "src/rpc.ts",
      "content": "// M6: settings-card RPC (decision 1 = Plan B; transport reworked in v1.2.1, C21).\n//\n// Host registers an exact Fetch route under /api via ctx.inject(['connection'], ...)\n// once the connection service mounts; the web card calls\n// connection.rpc.call('/api', 'heartbeat', { endpoint, ...payload }).\n// (The original custom channel '/heartbeat' via rpc.handle() is unusable on\n// DSH 0.1.5+: cordis pins the service's this.ctx to the provider context, so\n// handle()'s internal owner.webServer.register always fails strict resolution.)\n// Bindings authority = data/settings/bindings.json (decision 2); the card is\n// just another client of the same host logic the CLI uses.\n// Every endpoint runs inside the workspace guard; results are {ok,value} or\n// {ok:false,error:{code,message,details}}. Verbs are dispatched through a Map\n// and, when the host's /api gate is missing, only GATE_SAFE_ENDPOINTS serve\n// (⑦A / HB-19, 2026-10-17).\n\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport type { OrchestratorDeps } from './core/orchestrator.js';\nimport { getLastBeat, homeSessionId, resetHomeSession, pauseFocus, resumeFocus, getFocusUntil, formatFocusClock } from './core/orchestrator.js';\nimport { readFocusState, writeFocusState, clearFocusState } from './core/focus-store.js';\nimport { appendAuditLine } from './core/audit-log.js';\nimport type { UiConfig } from './config/ui-config.js';\nimport type { PathGuard } from './core/path-guard.js';\nimport { dshHomeDir } from './core/paths.js';\nimport { parseArchivedSessionIds, isArchivedSession } from './core/archived-sessions.js';\nimport { openPath } from './core/open-path.js';\nimport { localDayKey } from './core/time-window.js';\nimport type { WorkspacePaths } from './core/paths.js';\nimport { inQuietHours, readSentState } from './gate/gate.js';\nimport {\n  activeSeeds,\n  archivedSeeds,\n  archiveSeedById,\n  deleteSeed,\n  loadPool,\n  restoreSeed,\n  seedsFilePath,\n} from './seeds/pool.js';\nimport { loadProfile, profileFilePath } from './profile/store.js';\nimport { buildDigest } from './profile/digest.js';\nimport { ledgerFilePath } from './ledger/ledger.js';\nimport { EXCERPT_HEADER, excerptFilePath } from './excerpt/excerpt.js';\nimport { listWeeklyReports, readWeeklyReport } from './weekly/report.js';\nimport { addBinding, loadBindings, removeBinding } from './core/bindings.js';\nimport { addInterest, readEffective, removeInterest, setWanderWindows } from './browse/interests-edit.js';\nimport { writeText, loadJson } from './vault/vault.js';\nimport {\n  bilibiliSessionFilePath,\n  createBiliLoginService,\n  saveBiliSession,\n  type BiliSessionRecord,\n} from './cli/bili-login.js';\nimport { readStatus } from './statusbar/store.js';\nimport { loadTimeInjectState } from './statusbar/time-inject.js';\nimport type { Policy } from './config/schema.js';\n\n/** Exact Fetch route under /api (C21: custom rpc.handle channels are unusable\n * under 0.1.5's strict cordis service resolution — see installHeartbeatRpc). */\nexport const RPC_ROUTE_PATH = '/api/heartbeat';\n\n/**\n * ⑦A (2026-10-17 review, tightening H-41): the host's `/api` prefix gate is the\n * only authentication this route has — the plugin holds no credential of its own.\n * When that gate cannot be found the route fails closed: every verb is refused\n * except this short list of read-only, low-sensitivity ones (liveness plus what\n * the settings card needs to render). H-41+HB-19 refused six \"destructive\" verbs\n * and served everything else, which left every memory-bearing read —\n * `profile.digest`, `profile.partitions`, `seeds.list`, `interests.list`,\n * `weekly.get`, `migrate.export` — open to anything that could POST to loopback.\n */\nconst GATE_SAFE_ENDPOINTS = new Set([\n  'status',\n  'config.get',\n  'sessions.list',\n  'bindings.get',\n  'weekly.list',\n]);\n\ninterface RpcDeps {\n  ctx: OrchestratorDeps['ctx'] & {\n    inject(services: string[], callback: (scoped: unknown) => void): void;\n  };\n  paths: WorkspacePaths;\n  guard: PathGuard;\n  policy: Policy;\n  /** Card-edited rhythm values (v1.7.0): live view getter + persist-and-apply setter. */\n  ui: {\n    get(): {\n      intervalMin: number;\n      maxDailySend: number;\n      timeInjectMin: number;\n      statusbar: boolean;\n      idleMode: boolean;\n      tokenSaver: boolean;\n      psyEnabled: boolean;\n    };\n    set(patch: UiConfig & { psyEnabled?: boolean }): void;\n  };\n}\n\ntype RpcResult = { ok: true; value: unknown } | { ok: false; error: { code: string; message: string; details: Record<string, never> } };\n\nconst ok = (value: unknown): RpcResult => ({ ok: true, value });\nconst err = (code: string, message: string): RpcResult => ({ ok: false, error: { code, message, details: {} } });\n\nlet cachedVersion: string | null = null;\n/** Plugin version for the card's status block (read once from package.json). */\nfunction pluginVersion(paths: WorkspacePaths): string {\n  if (cachedVersion) return cachedVersion;\n  try {\n    const pkg = JSON.parse(fs.readFileSync(path.join(paths.packageRoot, 'package.json'), 'utf8')) as { version?: string };\n    cachedVersion = typeof pkg.version === 'string' ? pkg.version : 'unknown';\n  } catch {\n    cachedVersion = 'unknown';\n  }\n  return cachedVersion;\n}\n\n/** 素材池生命周期的审计出口（v1.9.0）：卡片上的归档/恢复/删除也留下痕迹。 */\nfunction seedAuditSink(paths: WorkspacePaths): (entry: Record<string, unknown>) => void {\n  return (entry) => {\n    try {\n      appendAuditLine(paths.logsDir + '/heartbeat.jsonl', entry);\n    } catch { /* audit must never break the RPC call */ }\n  };\n}\n\n/** 兴趣/时段卡片编辑的审计留痕（成功才记；失败原因走 RPC err 回给卡片）。 */\nfunction auditInterests(paths: WorkspacePaths, action: string, r: { ok: boolean }, detail: unknown): void {\n  try {\n    appendAuditLine(paths.logsDir + '/heartbeat.jsonl', {\n      event: `interests_${r.ok ? 'edit' : 'edit_failed'}`,\n      action,\n      detail: typeof detail === 'string' ? detail.slice(0, 80) : null,\n    });\n  } catch { /* audit must never break the RPC call */ }\n}\n\n/** Session titles from the host's projection cache. Titles are host data — the\n * client card merges them (client.js `nameOf`: title || id prefix).\n *\n * DSH 0.1.2 writes ONE RECORD PER SESSION under\n * `~/.dsh/storages/session_projcache/sessions/<sessionId>.json`\n * (`record.rows.title.val`). The single-file `session_projcache.json` we used\n * before is the older aggregate layout and goes stale: a session created after\n * the upgrade is simply absent from it, so `title` came back null and the card\n * printed the raw session id. Read the per-record layout FIRST, keep the\n * aggregate only as a legacy fallback. */\nfunction loadSessionTitles(): Record<string, string> {\n  const titles: Record<string, string> = {};\n  const take = (id: string, value: unknown): void => {\n    const t = value as { rows?: { title?: { val?: unknown } }; title?: { val?: unknown } } | undefined;\n    const row = t?.rows?.title ?? t?.title;\n    if (row && typeof row.val === 'string' && row.val && !titles[id]) titles[id] = row.val;\n  };\n  // 1) per-record layout (current).\n  try {\n    const dir = path.join(dshHomeDir(), 'storages', 'session_projcache', 'sessions');\n    for (const file of fs.readdirSync(dir)) {\n      if (!file.endsWith('.json')) continue;\n      const id = file.slice(0, -'.json'.length);\n      if (!id.startsWith('session-')) continue;\n      try {\n        const record = JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')) as { record?: unknown };\n        take(id, record.record);\n      } catch { /* skip a record we cannot read */ }\n    }\n  } catch { /* no per-record dir on older hosts */ }\n  // 2) legacy aggregate fallback.\n  try {\n    const raw = JSON.parse(fs.readFileSync(path.join(dshHomeDir(), 'storages', 'session_projcache.json'), 'utf8')) as unknown;\n    const walk = (node: unknown): void => {\n      if (!node || typeof node !== 'object') return;\n      for (const [key, value] of Object.entries(node as Record<string, unknown>)) {\n        if (key.startsWith('session-') && value && typeof value === 'object') {\n          // Title lives at <session>.rows.title.val (host title service); the\n          // val may be null while the title is still being generated.\n          take(key, value);\n        }\n        walk(value);\n      }\n    };\n    walk(raw);\n    return titles;\n  } catch {\n    return titles;\n  }\n}\n\n/** Host-side session registry (`~/.dsh/storages/workspace.json`) → the set of\n * session ids the USER actually sees in the sidebar.\n *\n * A persisted session is user-visible iff it belongs to some workspace's\n * `sessionIds` and is not in `archivedSessionIds`. Two exclusions fall out of\n * this for the bind picker (2026-09-30 user request):\n * - **archived** sessions (explicit `archivedSessionIds`, prefix formats are\n *   mixed on disk — some entries carry `session-`, some don't — so match\n *   both forms);\n * - **subagent child sessions**, which never join any workspace's\n *   `sessionIds` (observed: they only ever land in the archive list).\n *\n * Fail-open: a missing/corrupt registry returns `registryFound: false` and\n * the caller shows everything — an unreadable registry must not blank the\n * picker. The heartbeat home is always shown regardless (caller-side). */\nexport function loadVisibleSessionIds(registryFile?: string): { visible: Set<string>; registryFound: boolean } {\n  try {\n    const file = registryFile ?? path.join(dshHomeDir(), 'storages', 'workspace.json');\n    const text = fs.readFileSync(file, 'utf8');\n    // H-archived: the archived set + mixed-prefix match now come from the\n    // shared module (same disk truth the delivery lane filters on). The outer\n    // JSON.parse below still decides `registryFound`, so a valid registry with\n    // a non-array archived field keeps reporting registryFound: true.\n    const archived = parseArchivedSessionIds(text);\n    const j = JSON.parse(text) as {\n      tables?: { workspaces?: Record<string, { sessionIds?: unknown }> };\n    };\n    const visible = new Set<string>();\n    for (const ws of Object.values(j.tables?.workspaces ?? {})) {\n      const ids = Array.isArray(ws?.sessionIds) ? (ws.sessionIds as unknown[]) : [];\n      for (const raw of ids) {\n        const id = String(raw);\n        if (!isArchivedSession(archived, id)) visible.add(id);\n      }\n    }\n    return { visible, registryFound: true };\n  } catch {\n    return { visible: new Set(), registryFound: false };\n  }\n}\n\n/** One RPC verb: payload in, envelope out. `guard` / `paths` / `policy` / `deps`\n *  come from the closure built by {@link buildEndpoints}. */\ntype Endpoint = (p: Record<string, unknown>) => RpcResult | Promise<RpcResult>;\n\n/**\n * H-36: the endpoint table. This used to be a single `switch` at the bottom of\n * the route handler — 22 verbs and ~250 lines, with the guest list (which\n * endpoints exist) tangled up with the machinery (envelope validation, the\n * catch-all error wrapper). Adding a verb is now one entry here; the wrapper\n * stays in one place.\n */\nfunction buildEndpoints(deps: Omit<RpcDeps, 'ctx'>, isLive: (sessionId: string) => boolean): Record<string, Endpoint> {\n  const { guard, paths, policy } = deps;\n  // Bilibili QR login for the panel (v2.3.0): production wiring of the same\n  // service the CLI drives — real fetch + qrcode dataURL (no temp file) +\n  // vault-backed save. The session Map lives in this process's memory.\n  const biliLogin = createBiliLoginService({\n    fetchImpl: fetch,\n    renderQrDataUrl: async (url) => {\n      const { default: QRCode } = await import('qrcode');\n      return QRCode.toDataURL(url, { type: 'image/png', width: 400, margin: 2 });\n    },\n    now: () => Date.now(),\n    saveCredential: (value) => saveBiliSession(guard, paths, value),\n  });\n  return {\n    async status() {\n      const now = Date.now();\n      const sent = readSentState(guard, paths, now);\n      const beat = getLastBeat();\n      // M7 statusbar block (§17.8): store + throttle-state + live flags.\n      let lastTimeInjectAt: number | null = null;\n      try {\n        const state = loadTimeInjectState(guard, paths.dataDir);\n        for (const v of Object.values(state)) {\n          if (typeof v === 'number' && v > (lastTimeInjectAt ?? 0)) lastTimeInjectAt = v;\n        }\n      } catch { /* missing state file = never injected */ }\n      let flags = { statusbarEnabled: true, timeInjectMin: 25, idleMode: false };\n      try {\n        const { getRuntime } = await import('./core/runtime.js');\n        const f = getRuntime().flags;\n        flags = { statusbarEnabled: f.statusbarEnabled(), timeInjectMin: f.timeInjectMin(), idleMode: f.idleMode() };\n      } catch { /* pre-init: report defaults */ }\n      return ok({\n        now: new Date(now).toISOString(),\n        version: pluginVersion(paths),\n        intervalMin: policy.heartbeat.intervalMin,\n        idleMode: policy.heartbeat.idleMode,\n        cap: { used: sent.items.length, max: policy.gate.maxDailySend },\n        quiet: inQuietHours(policy, now),\n        lastBeat: beat,\n        homeSessionId: homeSessionId(guard, paths),\n        bindings: loadBindings(guard, paths.settingsDir).bindings.length,\n        statusbar: {\n          enabled: flags.statusbarEnabled,\n          timeInjectMin: flags.timeInjectMin,\n          lastStatus: readStatus(guard, paths),\n          lastTimeInjectAt: lastTimeInjectAt === null ? null : new Date(lastTimeInjectAt).toISOString(),\n        },\n      });\n    },\n\n    'sessions.list'() {\n      const root = path.join(dshHomeDir(), 'sessions');\n      const bindings = loadBindings(guard, paths.settingsDir).bindings;\n      const home = homeSessionId(guard, paths);\n      const titles = loadSessionTitles();\n      // Bind picker visibility: hide archived and subagent sessions\n      // (2026-09-30 user request). Fail-open when the registry is\n      // unreadable; the home is always listed.\n      const { visible, registryFound } = loadVisibleSessionIds();\n      const out: Record<string, unknown>[] = [];\n      if (fs.existsSync(root)) {\n        for (const slug of fs.readdirSync(root)) {\n          for (const id of fs.readdirSync(path.join(root, slug))) {\n            if (registryFound && id !== home && !visible.has(id)) continue;\n            const binding = bindings.find((b) => b.sessionId === id);\n            out.push({\n              id,\n              title: titles[id] ?? null,\n              cwdSlug: slug,\n              live: isLive(id),\n              home: id === home,\n              deliver: binding?.deliver ?? false,\n              observe: binding?.observe ?? false,\n            });\n          }\n        }\n      }\n      return ok({ sessions: out });\n    },\n\n    'bindings.get': () => ok(loadBindings(guard, paths.settingsDir)),\n\n    // Focus mode (v2.1.0 ①). The card and the CLI are two clients of the same\n    // pause: module state gives the host an immediate answer, data/focus.json\n    // carries it across processes (and survives a restart). `status` merges\n    // both so the card shows a pause the CLI set and vice versa.\n    'focus.status'() {\n      const now = Date.now();\n      const file = readFocusState(guard, paths, now);\n      const mem = getFocusUntil();\n      const until = Math.max(mem > now ? mem : 0, file?.until ?? 0);\n      return ok({\n        paused: until > now,\n        until: until > now ? new Date(until).toISOString() : null,\n        clock: until > now ? formatFocusClock(until) : null,\n        minutes: file?.minutes ?? null,\n        via: file?.via ?? (mem > now ? 'rpc' : null),\n      });\n    },\n\n    'focus.pause'(p) {\n      const raw = Number(p.minutes ?? 30);\n      if (!Number.isFinite(raw) || raw <= 0) return err('bad-request', 'minutes must be a positive number (1-1440)');\n      const now = Date.now();\n      const mem = pauseFocus(raw); // this process answers immediately\n      const file = writeFocusState(guard, paths, raw, now, 'settings-card');\n      const until = Math.max(mem, file.until);\n      return ok({\n        paused: true,\n        until: new Date(until).toISOString(),\n        clock: formatFocusClock(until),\n        minutes: file.minutes,\n      });\n    },\n\n    'focus.resume'() {\n      resumeFocus();\n      const removed = clearFocusState(guard, paths);\n      return ok({ paused: false, removed });\n    },\n\n    'bindings.add'(p) {\n      const id = String(p.sessionId ?? '');\n      if (!id.startsWith('session-')) return err('bad-request', 'sessionId must look like session-...');\n      const home = homeSessionId(guard, paths);\n      if (id === home) return err('bad-request', '该会话是心跳正身，无需绑定（决策轮次固定发生在正身）');\n      // Callers send BOTH flags explicitly (the card's per-flag toggles), so\n      // this stays a full-state write: deliver defaults on, observe off.\n      const b = addBinding(guard, paths.settingsDir, id, {\n        deliver: p.deliver !== false,\n        observe: p.observe === true,\n      });\n      return ok(b);\n    },\n\n    'bindings.remove'(p) {\n      const id = String(p.sessionId ?? '');\n      const removed = removeBinding(guard, paths.settingsDir, id);\n      // H-09/H-45: one shared release path — gate.json, the home_reset audit\n      // line and the orchestrator's cached agent — instead of an inline delete\n      // that silently left the in-memory home behind.\n      const homeReset = resetHomeSession(guard, paths, id);\n      return ok({ removed, homeReset });\n    },\n\n    'seeds.list'() {\n      const db = loadPool(guard, seedsFilePath(paths.dataDir));\n      return ok({\n        active: activeSeeds(db),\n        archived: archivedSeeds(db),\n        cap: policy.seeds.maxActive,\n      });\n    },\n\n    'seeds.archive'(p) {\n      const s = archiveSeedById(guard, seedsFilePath(paths.dataDir), String(p.id ?? ''), 'completed', Date.now(), seedAuditSink(paths));\n      return s ? ok(s) : err('not-found', 'active seed not found');\n    },\n\n    'seeds.restore'(p) {\n      const r = restoreSeed(guard, seedsFilePath(paths.dataDir), policy, String(p.id ?? ''), Date.now(), seedAuditSink(paths));\n      return r.ok ? ok(r.seed) : err('restore-failed', r.reason);\n    },\n\n    'seeds.delete'(p) {\n      return ok({ deleted: deleteSeed(guard, seedsFilePath(paths.dataDir), String(p.id ?? ''), seedAuditSink(paths)) });\n    },\n\n    // ── Bilibili QR login (v2.3.0): the panel's entry to the same login the\n    //    CLI drives. Failures come back as err(...) envelopes — nothing throws\n    //    at the card; the card maps poll states onto its own i18n texts.\n    'bili.status'() {\n      try {\n        const rec = loadJson<BiliSessionRecord>(guard, bilibiliSessionFilePath(paths));\n        const loggedIn = typeof rec?.sessdata === 'string' && rec.sessdata.length > 0;\n        return ok({\n          loggedIn,\n          savedAt: loggedIn && typeof rec!.savedAt === 'number' ? rec!.savedAt : null,\n        });\n      } catch {\n        // A missing/damaged vault container reads as \"not logged in\" — the\n        // card must still render, the CLI remains the repair path.\n        return ok({ loggedIn: false, savedAt: null });\n      }\n    },\n\n    async 'bili.login.start'() {\n      try {\n        return ok(await biliLogin.startBiliLogin());\n      } catch (e) {\n        return err('bili-login-failed', String(e instanceof Error ? e.message : e).slice(0, 200));\n      }\n    },\n\n    async 'bili.login.poll'(p) {\n      const sessionId = String(p.sessionId ?? '');\n      if (!sessionId) return err('bad-request', 'sessionId is required');\n      try {\n        return ok(await biliLogin.pollBiliLogin(sessionId));\n      } catch (e) {\n        return err('bili-login-failed', String(e instanceof Error ? e.message : e).slice(0, 200));\n      }\n    },\n\n    // ── 兴趣范围 / 浏览时段（v1.4.0；首编继承出厂，见 interests-edit.ts）──\n    'interests.list': () => ok(readEffective(paths)),\n\n    'interests.add'(p) {\n      const r = addInterest(guard, paths, String(p.text ?? ''));\n      auditInterests(paths, 'add', r, p.text);\n      return r.ok ? ok(r.doc) : err('bad-request', r.reason ?? 'add failed');\n    },\n\n    'interests.remove'(p) {\n      const r = removeInterest(guard, paths, String(p.text ?? ''));\n      auditInterests(paths, 'remove', r, p.text);\n      return r.ok ? ok(r.doc) : err('not-found', r.reason ?? 'remove failed');\n    },\n\n    'interests.setWindows'(p) {\n      const r = setWanderWindows(guard, paths, p.windows);\n      auditInterests(paths, 'set-windows', r, JSON.stringify(p.windows ?? null));\n      return r.ok ? ok(r.doc) : err('bad-request', r.reason ?? 'setWindows failed');\n    },\n\n    'config.get': () => ok(deps.ui.get()),\n\n    'config.set'(p) {\n      const patch = p as UiConfig;\n      if (!patch || typeof patch !== 'object' || Array.isArray(patch)) {\n        return err('bad-request', 'config.set needs a patch object');\n      }\n      const keys = Object.keys(patch).filter((k) =>\n        ['intervalMin', 'maxDailySend', 'timeInjectMin', 'statusbar', 'idleMode', 'tokenSaver', 'visionEngine', 'psyEnabled', 'quietStart', 'quietEnd'].includes(k),\n      );\n      if (keys.length === 0) return err('bad-request', 'config.set has no recognized field');\n      try {\n        deps.ui.set(patch);\n      } catch (e) {\n        return err('bad-request', String(e).slice(0, 120));\n      }\n      appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), { event: 'ui_config_set', keys });\n      return ok(deps.ui.get());\n    },\n\n    'profile.digest'() {\n      const d = buildDigest(guard, paths, policy, {});\n      return ok({\n        tact: d.tact,\n        topic: d.topic,\n        wander: d.wander,\n        withinBudget: d.withinBudget,\n        // v2.0 (item 6): the card shows the budget and what the caps dropped.\n        totalChars: d.totalChars,\n        budgetChars: d.budgetChars,\n        omitted: d.omitted,\n      });\n    },\n\n    'profile.partitions'() {\n      // v2.0 (item 6): the card shows ONE partition at a time, entry by entry.\n      // The digest view was a wall of text and never showed what the profile\n      // actually holds. Read-only, same data profile.export walks.\n      const doc = loadProfile(guard, profileFilePath(paths.dataDir));\n      const partitions: Record<string, { total: number; valid: number; entries: Record<string, unknown>[] }> = {};\n      for (const part of ['interest', 'projects', 'comm', 'psy'] as const) {\n        const all = doc.partitions[part]?.entries ?? [];\n        const valid = all.filter((e) => e.validTo === null);\n        partitions[part] = {\n          total: all.length,\n          valid: valid.length,\n          entries: valid\n            .slice()\n            .sort((a, b) => b.confidence - a.confidence || (a.updatedAt < b.updatedAt ? 1 : -1))\n            .map((e) => ({\n              id: e.id,\n              topic: e.topic,\n              subTopic: e.subTopic,\n              content: e.content,\n              confidence: e.confidence,\n              temporal: e.temporal,\n              updatedAt: e.updatedAt,\n              lowActivity: e.lowActivity === true,\n            })),\n        };\n      }\n      return ok({ partitions });\n    },\n\n    'profile.export'() {\n      const doc = loadProfile(guard, profileFilePath(paths.dataDir));\n      const lines = [`# 画像导出 ${new Date().toISOString()}`, ''];\n      for (const part of ['interest', 'projects', 'comm', 'psy'] as const) {\n        lines.push(`## ${part}`);\n        for (const e of doc.partitions[part]!.entries) {\n          if (e.validTo !== null) continue;\n          lines.push(`- [${e.topic}/${e.subTopic}] ${e.content} (conf ${e.confidence.toFixed(2)}, ${e.temporal})`);\n        }\n      }\n      const out = path.join(paths.exportsDir, `profile-export-${Date.now()}.md`);\n      writeText(guard, out, lines.join('\\n') + '\\n');\n      return ok({ path: out });\n    },\n\n    'ledger.open'() {\n      const f = ledgerFilePath(paths.dataDir);\n      if (!fs.existsSync(guard.assert(f))) fs.writeFileSync(f, '# 账本\\n', 'utf8');\n      openPath(f);\n      return ok({ path: f });\n    },\n\n    'excerpt.open'() {\n      const f = excerptFilePath(paths.dataDir);\n      if (!fs.existsSync(guard.assert(f))) fs.writeFileSync(f, EXCERPT_HEADER, 'utf8');\n      openPath(f);\n      return ok({ path: f });\n    },\n\n    'weekly.list': () => ok({ reports: listWeeklyReports(guard, paths.dataDir, policy.weekly.keepReports) }),\n\n    'weekly.get'(p) {\n      const file = String(p.file ?? '');\n      const rep = readWeeklyReport(guard, paths.dataDir, file);\n      if (!rep) return err('bad-request', `no such report: ${file}`);\n      return ok(rep);\n    },\n\n    async 'migrate.export'(p) {\n      // Card-side export (v1.8.0): same container as the CLI. The\n      // passphrase lives only in this call — never audited, never logged.\n      const passphrase = String(p.passphrase ?? '');\n      if (!passphrase) return err('bad-request', '需要设置口令');\n      const { collectMigrationEntries, encryptContainer } = await import('./vault/migrate.js');\n      const { entries } = collectMigrationEntries(guard, paths);\n      if (entries.length === 0) return err('bad-request', '没有可打包的记忆文件（data/ 是空的）');\n      const out = path.join(paths.exportsDir, `heartbeat-memory-${localDayKey()}.hbmig`);\n      writeText(guard, out, encryptContainer(entries, passphrase));\n      appendAuditLine(guard.assert(paths.logsDir + '/heartbeat.jsonl'), { event: 'migrate_export', files: entries.length });\n      return ok({ path: out, count: entries.length });\n    },\n\n    async 'migrate.import'(p) {\n      const passphrase = String(p.passphrase ?? '');\n      const file = String(p.file ?? '');\n      if (!passphrase || !file) return err('bad-request', '需要容器路径与口令');\n      const { decryptContainer, applyMigrationEntries } = await import('./